function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v >= 65536)) return 'Each value is an integer from 1 to 65535.';
  if (!Number.isInteger(k) || k < 1 || k > Math.floor(nums.length / 3)) return 'k is between 1 and floor(nums.length / 3).';
  return null;
}

