function maxSumOfThreeSubarrays(nums, k) {
  const prefix = [0];
  for (const value of nums) {
    prefix.push(prefix[prefix.length - 1] + value);
  }
  const count = nums.length - k + 1;
  const windowSum = [];
  for (let i = 0; i < count; i++) {
    windowSum.push(prefix[i + k] - prefix[i]);
  }

  const left = new Array(count);
  let best = 0;
  for (let i = 0; i < count; i++) {
    if (windowSum[i] > windowSum[best]) {
      best = i;
    }
    left[i] = best;
  }

  const right = new Array(count);
  best = count - 1;
  for (let i = count - 1; i >= 0; i--) {
    if (windowSum[i] >= windowSum[best]) {
      best = i;
    }
    right[i] = best;
  }

  let answer = [];
  let bestTotal = -1;
  for (let mid = k; mid + k < count; mid++) {
    const first = left[mid - k];
    const third = right[mid + k];
    const total = windowSum[first] + windowSum[mid] + windowSum[third];
    if (total > bestTotal) {
      bestTotal = total;
      answer = [first, mid, third];
    }
  }
  return answer;
}

