function maxSumOfThreeSubarrays(nums, k) {
  const sumAt = start => {
    let s = 0;
    for (let t = start; t < start + k; t++) s += nums[t];
    return s;
  };
  let best = -1;
  let answer = [];
  // Visiting a, b, c in increasing order and replacing only on a strictly larger total keeps the smallest list.
  for (let a = 0; a + 3 * k <= nums.length; a++) {
    for (let b = a + k; b + 2 * k <= nums.length; b++) {
      for (let c = b + k; c + k <= nums.length; c++) {
        const total = sumAt(a) + sumAt(b) + sumAt(c);
        if (total > best) {
          best = total;
          answer = [a, b, c];
        }
      }
    }
  }
  return answer;
}

