function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const k = rand() < 0.5 ? 1 + Math.floor(rand() * 50) : 1 + Math.floor(rand() * Math.floor(n / 3));
    const top = rand() < 0.5 ? 65535 : 3;
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top)), k];
  }
  const n = 3 + Math.floor(rand() * 10);
  const k = 1 + Math.floor(rand() * Math.floor(n / 3));
  const top = 1 + Math.floor(rand() * 5);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top)), k];
}
